#requires -RunAsAdministrator
#requires -Version 5.1
[CmdletBinding(SupportsShouldProcess)]param([string]$ManualPeer,[switch]$UseDomainHierarchy,[switch]$Rediscover)
$root='C:\ProgramData\BlueRidge\TimeSync';$logs='C:\ProgramData\BlueRidge\Logs';New-Item -ItemType Directory -Force -Path $root,$logs|Out-Null;$s=Get-Date -Format yyyyMMdd-HHmmss;$d=Join-Path $root "time-before-$s";New-Item -ItemType Directory -Force -Path $d|Out-Null;Start-Transcript -Path (Join-Path $logs 'time-sync-repair.log') -Append|Out-Null
try{w32tm /query /status|Out-File (Join-Path $d status.txt);w32tm /query /configuration|Out-File (Join-Path $d configuration.txt);w32tm /query /peers|Out-File (Join-Path $d peers.txt);Get-Service W32Time|Export-Csv (Join-Path $d service.csv) -NoTypeInformation;Set-Service W32Time -StartupType Automatic;Start-Service W32Time -ErrorAction SilentlyContinue;if($UseDomainHierarchy -and $PSCmdlet.ShouldProcess('Windows Time','Use domain hierarchy')){w32tm /config /syncfromflags:domhier /update|Out-Null};if($ManualPeer -and $PSCmdlet.ShouldProcess('Windows Time',"Use peer $ManualPeer")){w32tm /config /manualpeerlist:"$ManualPeer" /syncfromflags:manual /reliable:no /update|Out-Null};if($Rediscover){w32tm /resync /rediscover|Out-File (Join-Path $d resync.txt)}else{w32tm /resync|Out-File (Join-Path $d resync.txt)};w32tm /query /status;Write-Host "Before-state and results: $d" -ForegroundColor Green}finally{Stop-Transcript|Out-Null}
